#!/usr/bin/env python3
"""Customise the Android project generated by `tauri android init`.

The generated project (app/src-tauri/gen/android) is not committed, so CI re-creates it on every
build and runs this script afterwards. It is idempotent and fails loudly if the template changes.

- microphone, notification and Android 17 "local network" permissions (manifest + runtime request).
  Without ACCESS_LOCAL_NETWORK an app targeting SDK 37 cannot open TCP connections to servers on
  the home network; they just time out.
- a foreground service (FunkService) that keeps the process alive and shows a status notification
  that opens the app; Rust updates its text through FunkBridge (see src/android.rs).
- signing: builds are signed with the key named by FUNK_KEYSTORE / FUNK_KEYSTORE_PASSWORD (set by
  CI from a repository secret or a cached, CI-generated key; nothing secret is committed). A stable
  key lets a new APK update the installed app. Without those variables the default debug key is used.
- R8 keep rules: FunkBridge is looked up by name from Rust (JNI), release minification would
  otherwise strip it.
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent / "src-tauri" / "gen" / "android" / "app" / "src" / "main"
MANIFEST = ROOT / "AndroidManifest.xml"
KOTLIN_DIR = ROOT / "java" / "net" / "noert" / "mumblefunk"
ACTIVITY = KOTLIN_DIR / "MainActivity.kt"
GRADLE = ROOT.parent.parent / "build.gradle.kts"
PROGUARD = ROOT.parent.parent / "proguard-funk.pro"

PERMISSIONS = [
    "android.permission.RECORD_AUDIO",
    "android.permission.MODIFY_AUDIO_SETTINGS",
    "android.permission.ACCESS_LOCAL_NETWORK",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.WAKE_LOCK",
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_MICROPHONE",
    "android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK",
    # Only used when the user taps "Akku-Optimierung abschalten": opens Android's own dialog.
    "android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS",
]

SERVICE_XML = (
    '<service android:name=".FunkService" android:exported="false" '
    'android:foregroundServiceType="microphone|mediaPlayback" />'
)

ACTIVITY_KT = """package net.noert.mumblefunk

import android.Manifest
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.content.ContextCompat

class MainActivity : TauriActivity() {
  // Results are not needed here: the app reports a clear error if something is missing.
  private val permissions =
    registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { }

  private fun missingPermissions(): Array<String> {
    val wanted = mutableListOf(Manifest.permission.RECORD_AUDIO)
    // Android 17+: reaching servers on the local network needs its own runtime permission.
    if (Build.VERSION.SDK_INT >= 37) wanted.add("android.permission.ACCESS_LOCAL_NETWORK")
    // Android 13+: without this the status notification (and so the foreground service UI) is hidden.
    if (Build.VERSION.SDK_INT >= 33) wanted.add("android.permission.POST_NOTIFICATIONS")
    return wanted
      .filter { ContextCompat.checkSelfPermission(this, it) != PackageManager.PERMISSION_GRANTED }
      .toTypedArray()
  }

  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
    FunkDiag.log(this, "Activity onCreate (wiederhergestellt: ${savedInstanceState != null})")
    val missing = missingPermissions()
    if (missing.isNotEmpty()) permissions.launch(missing)
  }

  // The Rust side asks FunkBridge.isBackground() to decide how often to ping: rarer while the window is
  // not visible. Start-up counts as visible, so an unknown state never makes the radio less responsive.
  override fun onStart() {
    super.onStart()
    FunkBridge.uiVisible = true
    FunkDiag.log(this, "Activity onStart")
  }

  override fun onStop() {
    FunkBridge.uiVisible = false
    FunkDiag.log(this, "Activity onStop")
    super.onStop()
  }

  override fun onDestroy() {
    FunkDiag.log(this, "Activity onDestroy (beendet: $isFinishing, Konfigurationswechsel: $isChangingConfigurations)")
    super.onDestroy()
  }
}
"""


FUNK_BRIDGE_KT = """package net.noert.mumblefunk

import android.app.Activity
import android.content.ActivityNotFoundException
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.PowerManager
import android.provider.Settings
import android.util.Log

/** Called from Rust (JNI, see src/android.rs). Starts, updates or stops the status service, and more. */
object FunkBridge {
  /** True while the activity is started (window visible). Read by Rust through [isBackground]. */
  @Volatile
  @JvmField
  var uiVisible: Boolean = true

  @JvmStatic
  fun isBackground(): Boolean = !uiVisible

  @JvmStatic
  fun log(ctx: Context, text: String) {
    FunkDiag.log(ctx.applicationContext, text)
  }

  @JvmStatic
  fun report(ctx: Context): String =
    try {
      FunkDiag.report(ctx.applicationContext)
    } catch (e: Throwable) {
      "Diagnose nicht verfügbar: $e"
    }

  /** Opens Android's dialog that exempts this app from battery optimisation (user decides). */
  @JvmStatic
  fun requestBatteryExemption(act: Activity): Boolean {
    return try {
      val pm = act.getSystemService(PowerManager::class.java)
      val intent =
        if (pm.isIgnoringBatteryOptimizations(act.packageName)) {
          Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)
        } else {
          Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS, Uri.parse("package:" + act.packageName))
        }
      act.startActivity(intent)
      true
    } catch (e: ActivityNotFoundException) {
      false
    } catch (e: SecurityException) {
      false
    }
  }

  @JvmStatic
  fun update(ctx: Context, text: String, connected: Boolean) {
    val app = ctx.applicationContext
    if (!connected) {
      FunkDiag.log(app, "Dienst wird beendet")
      app.stopService(Intent(app, FunkService::class.java))
      return
    }
    FunkService.status = text
    try {
      if (FunkService.running) {
        FunkService.refresh(app)
      } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
        app.startForegroundService(Intent(app, FunkService::class.java))
      } else {
        app.startService(Intent(app, FunkService::class.java))
      }
    } catch (e: Exception) {
      Log.w("FunkBridge", "cannot start status service", e)
      FunkDiag.log(app, "Dienst konnte nicht gestartet werden: $e")
    }
  }
}
"""

FUNK_DIAG_KT = """package net.noert.mumblefunk

import android.app.ActivityManager
import android.app.usage.UsageStatsManager
import android.content.Context
import android.os.Build
import android.os.Debug
import android.os.PowerManager
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Small persistent event log plus a snapshot of everything that can explain why Android stops or
 * restricts the app. Contains no passwords or other secrets: only lifecycle events and error texts.
 */
object FunkDiag {
  private const val FILE = "diag.log"
  private const val MAX_BYTES = 48 * 1024
  private val lock = Any()

  private fun stamp(ms: Long): String = SimpleDateFormat("MM-dd HH:mm:ss", Locale.US).format(Date(ms))

  fun log(ctx: Context, msg: String) {
    synchronized(lock) {
      try {
        val f = File(ctx.filesDir, FILE)
        if (f.exists() && f.length() > MAX_BYTES) {
          // keep the newest half, starting at a line boundary
          val tail = f.readText().takeLast(MAX_BYTES / 2)
          f.writeText(tail.substringAfter('\\n', tail))
        }
        f.appendText(stamp(System.currentTimeMillis()) + " " + msg + "\\n")
      } catch (_: Throwable) {
        // logging must never disturb the radio
      }
    }
  }

  private fun bucketName(b: Int): String =
    when (b) {
      10 -> "ACTIVE"
      20 -> "WORKING_SET"
      30 -> "FREQUENT"
      40 -> "RARE"
      45 -> "RESTRICTED"
      50 -> "NEVER"
      else -> "UNBEKANNT($b)"
    }

  private fun reasonName(r: Int): String =
    when (r) {
      android.app.ApplicationExitInfo.REASON_ANR -> "ANR"
      android.app.ApplicationExitInfo.REASON_CRASH -> "CRASH"
      android.app.ApplicationExitInfo.REASON_CRASH_NATIVE -> "CRASH_NATIVE"
      android.app.ApplicationExitInfo.REASON_DEPENDENCY_DIED -> "DEPENDENCY_DIED"
      android.app.ApplicationExitInfo.REASON_EXCESSIVE_RESOURCE_USAGE -> "EXCESSIVE_RESOURCE_USAGE"
      android.app.ApplicationExitInfo.REASON_EXIT_SELF -> "EXIT_SELF"
      android.app.ApplicationExitInfo.REASON_FREEZER -> "FREEZER"
      android.app.ApplicationExitInfo.REASON_INITIALIZATION_FAILURE -> "INITIALIZATION_FAILURE"
      android.app.ApplicationExitInfo.REASON_LOW_MEMORY -> "LOW_MEMORY"
      android.app.ApplicationExitInfo.REASON_OTHER -> "OTHER"
      android.app.ApplicationExitInfo.REASON_PERMISSION_CHANGE -> "PERMISSION_CHANGE"
      android.app.ApplicationExitInfo.REASON_SIGNALED -> "SIGNALED"
      android.app.ApplicationExitInfo.REASON_USER_REQUESTED -> "USER_REQUESTED"
      android.app.ApplicationExitInfo.REASON_USER_STOPPED -> "USER_STOPPED"
      else -> "UNBEKANNT($r)"
    }

  fun report(ctx: Context): String {
    val sb = StringBuilder()
    val pkg = ctx.packageName
    try {
      val pi = ctx.packageManager.getPackageInfo(pkg, 0)
      sb.append("Mumble Funk ").append(pi.versionName).append('\\n')
    } catch (_: Throwable) {
    }
    sb.append("Gerät: ${Build.MANUFACTURER} ${Build.MODEL}, Android ${Build.VERSION.RELEASE} (SDK ${Build.VERSION.SDK_INT})\\n")
    val pm = ctx.getSystemService(PowerManager::class.java)
    val am = ctx.getSystemService(ActivityManager::class.java)
    sb.append("Akku-Optimierung für die App abgeschaltet: ${pm.isIgnoringBatteryOptimizations(pkg)}\\n")
    sb.append("Energiesparmodus: ${pm.isPowerSaveMode}, Doze: ${pm.isDeviceIdleMode}\\n")
    if (Build.VERSION.SDK_INT >= 28) {
      sb.append("Hintergrund eingeschränkt: ${am.isBackgroundRestricted}\\n")
      try {
        val usm = ctx.getSystemService(UsageStatsManager::class.java)
        sb.append("Standby-Bucket: ${bucketName(usm.appStandbyBucket)}\\n")
      } catch (_: Throwable) {
      }
    }
    sb.append("Dienst läuft: ${FunkService.running}, Fenster sichtbar: ${FunkBridge.uiVisible}\\n")
    try {
      val mi = am.getProcessMemoryInfo(intArrayOf(android.os.Process.myPid()))[0]
      val rt = Runtime.getRuntime()
      sb.append(
        "Speicher: ${mi.totalPss / 1024} MB gesamt (PSS), nativ ${Debug.getNativeHeapAllocatedSize() / 1048576} MB, " +
          "Java ${(rt.totalMemory() - rt.freeMemory()) / 1048576} MB\\n"
      )
    } catch (_: Throwable) {
    }
    if (Build.VERSION.SDK_INT >= 30) {
      try {
        val exits = am.getHistoricalProcessExitReasons(pkg, 0, 6)
        sb.append("Letzte Prozess-Enden (neueste zuerst):\\n")
        if (exits.isEmpty()) sb.append("  keine\\n")
        for (i in exits) {
          sb.append(
            "  ${stamp(i.timestamp)} ${reasonName(i.reason)} status=${i.status} importance=${i.importance} " +
              "pss=${i.pss / 1024}MB rss=${i.rss / 1024}MB ${i.description ?: ""}\\n"
          )
        }
      } catch (e: Throwable) {
        sb.append("Prozess-Enden nicht lesbar: $e\\n")
      }
    }
    sb.append("\\nEreignisse (neueste unten):\\n")
    synchronized(lock) {
      try {
        val lines = File(ctx.filesDir, FILE).readLines()
        for (l in lines.takeLast(60)) sb.append(l).append('\\n')
      } catch (_: Throwable) {
        sb.append("  (noch keine)\\n")
      }
    }
    return sb.toString()
  }
}
"""

FUNK_SERVICE_KT = """package net.noert.mumblefunk

import android.Manifest
import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.content.pm.ServiceInfo
import android.net.wifi.WifiManager
import android.os.Build
import android.os.IBinder
import android.os.PowerManager
import androidx.core.app.NotificationCompat
import androidx.core.app.ServiceCompat
import androidx.core.content.ContextCompat

/**
 * Foreground service: keeps the app process (and with it the Rust connection and audio) alive while
 * the screen is off and shows one status line. Tapping the notification opens the app.
 */
class FunkService : Service() {
  private var wakeLock: PowerManager.WakeLock? = null
  private var wifiLock: WifiManager.WifiLock? = null

  companion object {
    @Volatile var status: String = ""
    @Volatile var running: Boolean = false
    private const val CHANNEL_ID = "funk_status"
    private const val NOTIFICATION_ID = 1

    fun build(ctx: Context): Notification {
      val launch = ctx.packageManager.getLaunchIntentForPackage(ctx.packageName) ?: Intent()
      val pending = PendingIntent.getActivity(
        ctx, 0, launch, PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
      )
      return NotificationCompat.Builder(ctx, CHANNEL_ID)
        .setSmallIcon(android.R.drawable.ic_btn_speak_now)
        .setContentTitle("Mumble Funk")
        .setContentText(status)
        .setContentIntent(pending)
        .setOngoing(true)
        .setOnlyAlertOnce(true)
        .setCategory(NotificationCompat.CATEGORY_SERVICE)
        .setPriority(NotificationCompat.PRIORITY_LOW)
        .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
        .build()
    }

    fun refresh(ctx: Context) {
      ctx.getSystemService(NotificationManager::class.java).notify(NOTIFICATION_ID, build(ctx))
    }
  }

  override fun onCreate() {
    super.onCreate()
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
      val channel = NotificationChannel(CHANNEL_ID, "Funk-Status", NotificationManager.IMPORTANCE_LOW)
      channel.description = "Zeigt, dass Mumble Funk verbunden ist"
      getSystemService(NotificationManager::class.java).createNotificationChannel(channel)
    }
  }

  override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
    var types = ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK
    if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED) {
      types = types or ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE
    }
    ServiceCompat.startForeground(this, NOTIFICATION_ID, build(this), types)
    running = true
    FunkDiag.log(this, "Dienst gestartet (Typen $types)")
    acquireLocks()
    return START_NOT_STICKY
  }

  private fun acquireLocks() {
    if (wakeLock == null) {
      val pm = getSystemService(PowerManager::class.java)
      wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "MumbleFunk:radio").apply {
        setReferenceCounted(false)
        acquire()
      }
    }
    if (wifiLock == null) {
      val wm = applicationContext.getSystemService(WifiManager::class.java)
      val mode = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q)
        WifiManager.WIFI_MODE_FULL_LOW_LATENCY else @Suppress("DEPRECATION") WifiManager.WIFI_MODE_FULL_HIGH_PERF
      wifiLock = wm.createWifiLock(mode, "MumbleFunk:wifi").apply {
        setReferenceCounted(false)
        acquire()
      }
    }
  }

  override fun onDestroy() {
    running = false
    FunkDiag.log(this, "Dienst beendet")
    wakeLock?.let { if (it.isHeld) it.release() }
    wifiLock?.let { if (it.isHeld) it.release() }
    wakeLock = null
    wifiLock = null
    super.onDestroy()
  }

  override fun onBind(intent: Intent?): IBinder? = null
}
"""


SIGNING_BLOCK = """    signingConfigs {
        create("funk") {
            // Provided by CI; see .github/workflows/build.yml ("Prepare signing key").
            val keystore = System.getenv("FUNK_KEYSTORE")
            if (keystore != null) {
                storeFile = file(keystore)
                storePassword = System.getenv("FUNK_KEYSTORE_PASSWORD")
                keyAlias = "funk"
                keyPassword = System.getenv("FUNK_KEYSTORE_PASSWORD")
            }
        }
    }
"""

SIGNING_LINE = (
    '\n            signingConfig = signingConfigs.getByName('
    'if (System.getenv("FUNK_KEYSTORE") != null) "funk" else "debug")'
)

PROGUARD_RULES = """# Looked up by name from Rust via JNI (src/android.rs); must survive minification.
-keep class net.noert.mumblefunk.FunkBridge { *; }
-keep class net.noert.mumblefunk.FunkService { *; }
-keep class net.noert.mumblefunk.MainActivity { *; }
"""


def fail(msg: str) -> None:
    print(f"android-patch: {msg}", file=sys.stderr)
    sys.exit(1)


def patch_manifest() -> None:
    text = MANIFEST.read_text(encoding="utf-8")
    anchor = '<uses-permission android:name="android.permission.INTERNET" />'
    if anchor not in text:
        fail("INTERNET permission anchor not found in AndroidManifest.xml (template changed?)")
    for perm in PERMISSIONS:
        line = f'<uses-permission android:name="{perm}" />'
        if line not in text:
            text = text.replace(anchor, f"{anchor}\n    {line}", 1)
    if "FunkService" not in text:
        provider = "<provider"
        if provider not in text:
            fail("<provider> anchor not found in AndroidManifest.xml (template changed?)")
        text = text.replace(provider, f"{SERVICE_XML}\n\n        {provider}", 1)
    MANIFEST.write_text(text, encoding="utf-8")


def patch_activity() -> None:
    if not ACTIVITY.exists():
        fail(f"{ACTIVITY} not found")
    ACTIVITY.write_text(ACTIVITY_KT, encoding="utf-8")
    (KOTLIN_DIR / "FunkBridge.kt").write_text(FUNK_BRIDGE_KT, encoding="utf-8")
    (KOTLIN_DIR / "FunkDiag.kt").write_text(FUNK_DIAG_KT, encoding="utf-8")
    (KOTLIN_DIR / "FunkService.kt").write_text(FUNK_SERVICE_KT, encoding="utf-8")


def patch_gradle() -> None:
    text = GRADLE.read_text(encoding="utf-8")
    if 'create("funk")' not in text:
        anchor = "    buildTypes {"
        if anchor not in text:
            fail("buildTypes anchor not found in build.gradle.kts (template changed?)")
        text = text.replace(anchor, SIGNING_BLOCK + anchor, 1)
        for build_type in ("debug", "release"):
            head = f'getByName("{build_type}") {{'
            if head not in text:
                fail(f"{head} not found in build.gradle.kts (template changed?)")
            text = text.replace(head, head + SIGNING_LINE, 1)
        GRADLE.write_text(text, encoding="utf-8")
    PROGUARD.write_text(PROGUARD_RULES, encoding="utf-8")


for p in (MANIFEST, ACTIVITY, GRADLE):
    if not p.exists():
        fail(f"{p} not found - run `cargo tauri android init` first")
patch_manifest()
patch_activity()
patch_gradle()
print("android-patch: applied")
